#include "stdlib/stats/base/dists/lognormal/kurtosis.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/expm1.h"

/**
* Returns the excess kurtosis for a lognormal distribution with location `mu` and scale `sigma`.
*
* ## Method
*
* The excess kurtosis is
*
* ```tex
* e^{4\sigma^2} + 2e^{3\sigma^2} + 3e^{2\sigma^2} - 6
* ```
*
* which cancels for small \\(\sigma\\). With \\(u = e^{\sigma^2} - 1\\), evaluated by `expm1`, it expands to
*
* ```tex
* u(16 + u(15 + u(6 + u)))
* ```
*
* whose terms are all positive.
*
* @param mu       location parameter
* @param sigma    scale parameter
* @return         excess kurtosis
*
* @example
* double y = stdlib_base_dists_lognormal_kurtosis( 0.0, 1.0 );
* // returns ~110.936
*/
double stdlib_base_dists_lognormal_kurtosis( const double mu, const double sigma ) {
	double u;
	if (
		stdlib_base_is_nan( mu ) ||
		stdlib_base_is_nan( sigma ) ||
		sigma <= 0.0
	) {
		return 0.0/0.0; // NaN
	}
	u = stdlib_base_expm1( sigma * sigma );
	return u * ( 16.0 + ( u * ( 15.0 + ( u * ( 6.0 + u ) ) ) ) );
}
